// The Last Footprint · offline cache (service worker). Generated by build.py from tools/sw.js.
// First visit: keeps the core files (page, code, Mars textures, rover model, fonts, images).
// Voices and the Earth texture are kept the first time they are downloaded.
// Second visit: everything opens from the device, with or without internet.
// A new version of the site gets a new cache name, and the old cache is deleted.
const VERSION = '2a75d1c62e7b';
const CACHE = 'tlf-' + VERSION;
const CORE = ["./", "index.html", "app.js?v=2a75d1c62e7b", "models/space-tex.js?v=2a75d1c62e7b", "models/MER.glb", "fonts/chakra-petch-latin-500-normal.woff2", "fonts/chakra-petch-latin-600-normal.woff2", "fonts/ibm-plex-sans-arabic-arabic-400-normal.woff2", "fonts/ibm-plex-sans-arabic-arabic-600-normal.woff2", "fonts/ibm-plex-sans-arabic-latin-400-normal.woff2", "fonts/ibm-plex-sans-arabic-latin-600-normal.woff2", "fonts/lalezar-arabic-400-normal.woff2", "assets/PIA00405.jpg", "assets/PIA00407.jpg", "assets/PIA00971.jpg", "assets/PIA05547.jpg", "assets/PIA12205.jpg", "assets/PIA21906.jpg", "assets/PIA22908.jpg"];

self.addEventListener('install', (e) => {
  // each file on its own, so one missing file never blocks the rest
  e.waitUntil(caches.open(CACHE).then((c) => Promise.all(CORE.map((u) => c.add(u).catch(() => {})))).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys()
    .then((keys) => Promise.all(keys.filter((k) => k.startsWith('tlf-') && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// audio elements ask for byte ranges; answer them from the cached file
async function ranged(req, res) {
  const m = /bytes=(\d+)-(\d*)/.exec(req.headers.get('range') || '');
  if (!m) return res;
  const buf = await res.arrayBuffer();
  const start = +m[1], end = m[2] ? Math.min(+m[2], buf.byteLength - 1) : buf.byteLength - 1;
  return new Response(buf.slice(start, end + 1), {
    status: 206,
    headers: { 'Content-Type': res.headers.get('Content-Type') || 'audio/mpeg', 'Content-Range': `bytes ${start}-${end}/${buf.byteLength}`, 'Content-Length': String(end - start + 1), 'Accept-Ranges': 'bytes' },
  });
}

self.addEventListener('fetch', (e) => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== location.origin) return; // Google Sheet, Google Fonts: straight to the network
  const key = req.mode === 'navigate' ? url.origin + url.pathname : req.url; // the page: ignore ?lang=…; files: keep ?v= (the version)
  // the page itself: newest from the network when online, the saved copy when offline
  if (req.mode === 'navigate') {
    e.respondWith(fetch(req).then((res) => { const c = res.clone(); caches.open(CACHE).then((x) => x.put(key, c)); return res; })
      .catch(() => caches.match(key).then((r) => r || caches.match(new URL('./index.html', self.registration.scope).href))));
    return;
  }
  e.respondWith(caches.open(CACHE).then(async (c) => {
    const hit = await c.match(key);
    if (hit) return req.headers.has('range') ? ranged(req, hit) : hit;
    const res = await fetch(req.headers.has('range') ? key : req); // fetch the whole file once, then keep it
    if (res.ok && res.status === 200) { await c.put(key, res.clone()); return req.headers.has('range') ? ranged(req, res) : res; }
    return res;
  }).catch(() => fetch(req)));
});
